-- Uptime application schema for PostgreSQL.
-- Run against the existing "Uptime" database as its owner.
-- This script creates missing objects and preserves existing rows.

BEGIN;

SET LOCAL ROLE uptime_owner;

CREATE TABLE IF NOT EXISTS "UptimeStudentProfiles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FirstName" varchar(80) NOT NULL,
    "LastName" varchar(80) NOT NULL,
    "PreferredName" varchar(80),
    "InstitutionName" varchar(150) NOT NULL,
    "Email" varchar(150),
    "CreatedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_UptimeStudentProfiles_Email"
    ON "UptimeStudentProfiles" ("Email")
    WHERE "Email" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "UptimeRingtones" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(80) NOT NULL,
    "Category" varchar(40) NOT NULL,
    "AudioFilePath" varchar(250) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "UptimeClassSchedules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL,
    "Course" varchar(150) NOT NULL,
    "DayOfWeek" varchar(10) NOT NULL,
    "StartTime" time(0) without time zone NOT NULL,
    "EndTime" time(0) without time zone NOT NULL,
    "Venue" varchar(150) NOT NULL,
    "Instructor" varchar(120),
    CONSTRAINT "FK_ClassSchedules_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_UptimeClassSchedules_Day"
        CHECK ("DayOfWeek" IN ('Sun', 'Sat', 'Fri', 'Thu', 'Wed', 'Tue', 'Mon')),
    CONSTRAINT "CK_UptimeClassSchedules_Time"
        CHECK ("EndTime" > "StartTime")
);

CREATE TABLE IF NOT EXISTS "UptimeCalendarEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL,
    "Title" varchar(150) NOT NULL,
    "EventDate" date NOT NULL,
    "EventTime" time(0) without time zone,
    "Description" varchar(1000),
    CONSTRAINT "FK_CalendarEvents_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "UptimeExpenses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Amount" numeric(10,2) NOT NULL,
    "Category" varchar(50) NOT NULL,
    "ExpenseDate" date NOT NULL,
    CONSTRAINT "FK_Expenses_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_UptimeExpenses_Amount" CHECK ("Amount" > 0)
);

CREATE TABLE IF NOT EXISTS "UptimeStudentTasks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL,
    "Title" varchar(180) NOT NULL,
    "Description" varchar(1000),
    "DueDate" date,
    "Status" varchar(20) NOT NULL DEFAULT 'Pending',
    "Priority" varchar(20) NOT NULL DEFAULT 'Normal',
    "CreatedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudentTasks_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_UptimeStudentTasks_Priority"
        CHECK ("Priority" IN ('High', 'Normal', 'Low')),
    CONSTRAINT "CK_UptimeStudentTasks_Status"
        CHECK ("Status" IN ('Completed', 'In Progress', 'Pending'))
);

CREATE TABLE IF NOT EXISTS "UptimeStudySessions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL,
    "Subject" varchar(150) NOT NULL,
    "DurationMinutes" integer NOT NULL,
    "StartedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_StudySessions_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_UptimeStudySessions_Duration"
        CHECK ("DurationMinutes" BETWEEN 1 AND 1440)
);

CREATE TABLE IF NOT EXISTS "UptimeStudentSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL UNIQUE,
    "ReminderMinutes" integer NOT NULL DEFAULT 60,
    "NotificationsEnabled" boolean NOT NULL DEFAULT TRUE,
    "RingtoneEnabled" boolean NOT NULL DEFAULT TRUE,
    "Volume" integer NOT NULL DEFAULT 70,
    "MonthlyBudgetLimit" numeric(10,2) NOT NULL DEFAULT 500,
    CONSTRAINT "FK_StudentSettings_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_StudentSettings_Budget" CHECK ("MonthlyBudgetLimit" > 0),
    CONSTRAINT "CK_StudentSettings_Reminder" CHECK ("ReminderMinutes" BETWEEN 1 AND 1440),
    CONSTRAINT "CK_StudentSettings_Volume" CHECK ("Volume" BETWEEN 0 AND 100)
);

CREATE TABLE IF NOT EXISTS "UptimeAlarms" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId" integer NOT NULL,
    "Label" varchar(100) NOT NULL DEFAULT 'Alarm',
    "AlarmTime" time(0) without time zone NOT NULL,
    "IsEnabled" boolean NOT NULL DEFAULT TRUE,
    "RepeatDays" varchar(13) NOT NULL DEFAULT '',
    "RingtoneId" integer NOT NULL,
    "CreatedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp(6) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_Alarms_Ringtones"
        FOREIGN KEY ("RingtoneId") REFERENCES "UptimeRingtones"("Id"),
    CONSTRAINT "FK_Alarms_StudentProfiles"
        FOREIGN KEY ("StudentId") REFERENCES "UptimeStudentProfiles"("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_UptimeAlarms_RepeatDays"
        CHECK ("RepeatDays" = '' OR "RepeatDays" !~ '[^1-7,]')
);

CREATE INDEX IF NOT EXISTS "IX_UptimeClassSchedules_Student_Day_Time"
    ON "UptimeClassSchedules" ("StudentId", "DayOfWeek", "StartTime");
CREATE INDEX IF NOT EXISTS "IX_UptimeCalendarEvents_Student_Date"
    ON "UptimeCalendarEvents" ("StudentId", "EventDate");
CREATE INDEX IF NOT EXISTS "IX_UptimeExpenses_Student_Date"
    ON "UptimeExpenses" ("StudentId", "ExpenseDate");
CREATE INDEX IF NOT EXISTS "IX_UptimeStudentTasks_Student_DueDate"
    ON "UptimeStudentTasks" ("StudentId", "DueDate");
CREATE INDEX IF NOT EXISTS "IX_UptimeStudySessions_Student_Started"
    ON "UptimeStudySessions" ("StudentId", "StartedAt");
CREATE INDEX IF NOT EXISTS "IX_UptimeAlarms_Student_Time"
    ON "UptimeAlarms" ("StudentId", "IsEnabled", "AlarmTime");

INSERT INTO "UptimeRingtones" ("Id", "Name", "Category", "AudioFilePath", "IsActive")
VALUES
    (1, 'Rising Bell', 'Samsung-inspired', '/audio/tone1.wav', TRUE),
    (2, 'Orbit Chime', 'Samsung-inspired', '/audio/tone2.wav', TRUE),
    (3, 'Soft Horizon', 'Samsung-inspired', '/audio/tone3.wav', TRUE),
    (4, 'Marimba Pulse', 'iPhone-inspired', '/audio/tone4.wav', TRUE),
    (5, 'Radar Ping', 'iPhone-inspired', '/audio/tone5.wav', TRUE),
    (6, 'Twin Drops', 'iPhone-inspired', '/audio/tone6.wav', TRUE),
    (7, 'Aurora', 'Huawei-inspired', '/audio/tone7.wav', TRUE),
    (8, 'Crystal Ping', 'Huawei-inspired', '/audio/tone8.wav', TRUE),
    (9, 'Calm Waves', 'Huawei-inspired', '/audio/tone9.wav', TRUE)
ON CONFLICT ("Id") DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('"UptimeRingtones"', 'Id'),
    GREATEST(COALESCE((SELECT MAX("Id") FROM "UptimeRingtones"), 1), 1),
    EXISTS (SELECT 1 FROM "UptimeRingtones")
);

GRANT CONNECT ON DATABASE "Uptime" TO uptime_app;
GRANT USAGE ON SCHEMA public TO uptime_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO uptime_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO uptime_app;
ALTER DEFAULT PRIVILEGES FOR ROLE uptime_owner IN SCHEMA public
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO uptime_app;
ALTER DEFAULT PRIVILEGES FOR ROLE uptime_owner IN SCHEMA public
    GRANT USAGE, SELECT ON SEQUENCES TO uptime_app;

COMMIT;
